public class LinkedListCycle {

    static class ListNode {
        int val;
        ListNode next;
        ListNode(int val) { this.val = val; }
    }

    // LeetCode 141：判断是否有环
    public boolean hasCycle(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) return true;
        }
        return false;
    }

    // LeetCode 142：找环入口（面试高频追问）
    // 原理：相遇后，一个指针从 head 出发、一个从相遇点出发，各走一步，再次相遇即入口
    public ListNode detectCycle(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {          // 相遇
                ListNode entry = head;
                while (entry != slow) {  // 从 head 和相遇点各走一步
                    entry = entry.next;
                    slow = slow.next;
                }
                return entry;            // 环入口
            }
        }
        return null;                     // 无环
    }

    // 计算环长：相遇后一个指针不动，另一个走一圈回来
    public int cycleLength(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {
                int len = 1;
                ListNode p = slow.next;
                while (p != slow) {
                    p = p.next;
                    len++;
                }
                return len;
            }
        }
        return 0;
    }

    public static void main(String[] args) {
        LinkedListCycle s = new LinkedListCycle();

        // 3->2->0->-4->(回到2)  有环
        ListNode h1 = new ListNode(3), n2 = new ListNode(2);
        ListNode n0 = new ListNode(0), n4 = new ListNode(-4);
        h1.next = n2; n2.next = n0; n0.next = n4; n4.next = n2;
        System.out.println(s.hasCycle(h1));       // true
        System.out.println(s.detectCycle(h1).val); // 2（环入口）
        System.out.println(s.cycleLength(h1));    // 3

        // 1->2  无环
        ListNode h2 = new ListNode(1);
        h2.next = new ListNode(2);
        System.out.println(s.hasCycle(h2));       // false
        System.out.println(s.detectCycle(h2));    // null
    }
}
